  ('riddle', 'roof', 'Motorun sıcak sıvısı ince kanallarımdan geçer. Hava, metal yüzeylerimden ısıyı alır.', 'radyatör', array['motor radyatörü']::text[], array[]::text[]),
  ('riddle', 'roof', 'Mıknatısın yanına serpiştirilince görünmez alanın çizgilerine dizilen küçük metal kırıntılarıyız.', 'demir talaşı', array[]::text[], array[]::text[]),
  ('riddle', 'roof', 'Hava basıncını okurum. Cıvalı olanımda basınç değişince ince sütun yükselir ya da alçalır.', 'barometre', array['basınçölçer']::text[], array[]::text[]),
  ('riddle', 'roof', 'Yerin titreşimlerini çizgi hâlinde kaydederim. Depremi hissetmeyen biri bile çizgimde izini görebilir.', 'sismograf', array['depremölçer','sismometre']::text[], array[]::text[]),
  ('riddle', 'roof', 'On uzantımın ikisi ötekilerden uzundur. Kaçarken adımı aldığım koyu bir sıvı bırakırım.', 'mürekkep balığı', array['sübye','sepya']::text[], array[]::text[]),
  ('riddle', 'roof', 'Orkestrada ayakta çalınacak kadar büyüğüm. Yaylı ailenin en pes seslerinden birini çıkarırım.', 'kontrbas', array[]::text[], array[]::text[]),
