  ('riddle', 'roof', 'Rüzgâr estikçe küçük kaplarım döner. Dönüş hızlarından rüzgârın hızını bulurum.', 'anemometre', array['rüzgâr ölçer','rüzgar ölçer']::text[], array[]::text[]),
