  ('riddle', 'roof', 'Yüksek kulemde uzun kanatlarım var. Hava onları döndürür, içimdeki jeneratör elektrik üretir.', 'rüzgâr türbini', array[]::text[], array[]::text[])
)
insert into public.questions(kind,tier,prompt,answer,accepted_answers,hints,language)
select n.kind::public.question_kind,n.tier::public.question_tier,n.prompt,n.answer,n.accepted_answers,n.hints,'tr'
from new_questions n
where not exists (
  select 1 from public.questions old
  where old.language='tr' and old.kind=n.kind::public.question_kind
    and public.norm_answer(old.answer)=public.norm_answer(n.answer)
);
